// src/social/followMeUrl.ts
function buildFollowMeUrl(platform, handle) {
  switch (platform) {
    case "x":
      return `https://x.com/${handle}`;
    case "instagram":
      return `https://www.instagram.com/${handle}/`;
    case "tiktok":
      return `https://www.tiktok.com/@${handle}`;
    case "discord":
      return `https://discord.gg/${handle}`;
    default: {
      const _exhaustive = platform;
      return _exhaustive;
    }
  }
}

