  /**
   * Auto-create a game via the Game Manager API (playground only).
   * After creation, writes the config file via the Vite middleware and reloads.
   */
  async autoCreatePlaygroundGame(user, playgroundConfig) {
    const createStart = Date.now();
    try {
      const idToken = await user.getIdToken();
      const gameManagerUrl = playgroundConfig.gameManagerUrl;
      const createResponse = await fetch(
        `${gameManagerUrl}/v1/games/createGame`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${idToken}`
          },
          body: JSON.stringify({
            name: "Playground Game",
            description: "Auto-created playground game for local development"
          })
        }
      );
      if (!createResponse.ok) {
        const text = await createResponse.text();
        throw new Error(
          `Game creation failed (${createResponse.status}): ${text}`
        );
      }
      const createResponseBody = await createResponse.json();
      const responseData = createResponseBody;
      const newGameId = responseData.data?.id || responseData.id;
      if (!newGameId) {
        throw new Error(
          `Game Manager returned empty game ID. Full response: ${JSON.stringify(createResponseBody)}`
        );
      }
      const writeResponse = await fetch("/__rundot-write-game-config", {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Rundot-Playground": "1" },
        body: JSON.stringify({ gameId: newGameId, target: "playground" })
      });
      if (!writeResponse.ok) {
        console.warn(
          "[RUN:playground] Failed to write game config file, but game was created"
        );
      }
      if (window.__RUNDOT_GAME_PLAYGROUND__) {
        window.__RUNDOT_GAME_PLAYGROUND__.gameId = newGameId;
      }
      sessionStorage.setItem("rundot-playground-game-created", "1");
      markBootPhase("game-create:reload");
      expectBootReload();
      window.location.reload();
      markBootPhase("game-create", Date.now() - createStart);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(
        "[RUN:playground] Failed to auto-create game:",
        message
      );
      markBootPhase("game-create:error", Date.now() - createStart);
      if (this.stateMachine) {
        this.stateMachine.setError(message);
      }
    }
  }
  /**
   * Upload merged server config to VGM and link it via the "private" tag.
   * This enables simulation APIs to work in playground by ensuring the game
   * has a server config in Firestore.
   */
  async uploadServerConfig(user, playgroundConfig) {
    try {
      const configResponse = await fetch("/__rundot-server-config", {
        headers: { "X-Rundot-Playground": "1" }
      });
      if (configResponse.status === 404) {
        markBootPhase("server-config-upload:skipped");
        return false;
      }
      if (!configResponse.ok) {
        const body = await configResponse.text();
        console.error(
          "[RUN:playground] Server config merge error:",
          body
        );
        markBootPhase("server-config-upload:failed");
        return false;
      }
      const configPayload = await configResponse.json();
      const mergedConfig = configPayload.config;
      const configHash = configPayload.hash;
      if (!mergedConfig || Object.keys(mergedConfig).length === 0) {
        markBootPhase("server-config-upload:skipped");
        return false;
      }
      if (!configPayload.changed) {
        markBootPhase("server-config-upload:skipped");
        return false;
      }
      const idToken = await user.getIdToken();
      const gameManagerUrl = playgroundConfig.gameManagerUrl;
      if (!gameManagerUrl) {
        console.warn(
          "[RUN:playground] No Game Manager URL configured, cannot upload server config"
        );
        markBootPhase("server-config-upload:skipped");
        return false;
      }
      const gameId = playgroundConfig.gameId;
      if (!gameId) {
        markBootPhase("server-config-upload:skipped");
        return false;
      }
      const uploadResponse = await fetch(
        `${gameManagerUrl}/v1/games/${gameId}/uploadServer`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${idToken}`
          },
          body: JSON.stringify({ value: mergedConfig })
        }
      );
      if (!uploadResponse.ok) {
        const text = await uploadResponse.text();
        console.warn(
          `[RUN:playground] Server config upload failed (${uploadResponse.status}): ${text}`
        );
        markBootPhase("server-config-upload:failed");
        return false;
      }
      const uploadBody = await uploadResponse.json();
      const serverId = uploadBody.data?.id || uploadBody.id;
      if (!serverId) {
        console.warn(
          "[RUN:playground] Server config upload returned no serverId"
        );
        markBootPhase("server-config-upload:failed");
        return false;
      }
      const tagResponse = await fetch(
        `${gameManagerUrl}/v1/games/${gameId}/tags`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${idToken}`
          },
          body: JSON.stringify({ tag: "private", serverId, name: "private" })
        }
      );
      if (!tagResponse.ok) {
        const text = await tagResponse.text();
        console.warn(
          `[RUN:playground] Tag update failed (${tagResponse.status}): ${text}`
        );
        markBootPhase("server-config-upload:failed");
        return false;
      }
      try {
        await fetch("/__rundot-server-config-hash", {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Rundot-Playground": "1" },
          body: JSON.stringify({ hash: configHash })
        });
      } catch {
        console.warn(
          "[RUN:playground] Failed to persist config hash (non-critical)"
        );
      }
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn(
        "[RUN:playground] Server config upload error:",
        message
      );
      markBootPhase("server-config-upload:failed");
      return false;
    }
  }
